import java.util.*;
public class PlayfairCipher {static char[][] m=new char[5][5];static int[] pos(char x){for(int r=0;r<5;r++)for(int c=0;c<5;c++)if(m[r][c]==x)return new int[]{r,c};return new int[]{0,0};}static String run(String s,boolean dec){StringBuilder o=new StringBuilder();for(int i=0;i<s.length();i+=2){int[] a=pos(s.charAt(i)),b=pos(s.charAt(i+1));if(a[0]==b[0])o.append(m[a[0]][Math.floorMod(a[1]+(dec?-1:1),5)]).append(m[b[0]][Math.floorMod(b[1]+(dec?-1:1),5)]);else if(a[1]==b[1])o.append(m[Math.floorMod(a[0]+(dec?-1:1),5)][a[1]]).append(m[Math.floorMod(b[0]+(dec?-1:1),5)][b[1]]);else o.append(m[a[0]][b[1]]).append(m[b[0]][a[1]]);}return o.toString();}public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter key: ");String key=sc.nextLine().toUpperCase().replace('J','I');System.out.print("Enter plaintext: ");String p=sc.nextLine().toUpperCase().replace('J','I').replaceAll("[^A-Z]","");StringBuilder seq=new StringBuilder();for(char x:(key+"ABCDEFGHIKLMNOPQRSTUVWXYZ").toCharArray())if(x>='A'&&x<='Z'&&seq.indexOf(""+x)<0)seq.append(x);for(int i=0;i<25;i++)m[i/5][i%5]=seq.charAt(i);StringBuilder prep=new StringBuilder();for(int i=0;i<p.length();){char x=p.charAt(i),y=(i+1<p.length()?p.charAt(i+1):'X');if(x==y){prep.append(x).append('X');i++;}else{prep.append(x).append(y);i+=2;}}if(prep.length()%2!=0)prep.append('X');String ct=run(prep.toString(),false);System.out.println("Ciphertext: "+ct);System.out.println("Decrypted: "+run(ct,true));}}
